CREATE TABLE system_roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, role_code VARCHAR(50) NOT NULL UNIQUE, role_name VARCHAR(100) NOT NULL, data_scope VARCHAR(20) NOT NULL DEFAULT 'SELF', built_in TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, permission_code VARCHAR(100) NOT NULL UNIQUE, permission_name VARCHAR(100) NOT NULL);
CREATE TABLE system_role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY (role_id,permission_id), CONSTRAINT fk_rp_role FOREIGN KEY(role_id) REFERENCES system_roles(id), CONSTRAINT fk_rp_permission FOREIGN KEY(permission_id) REFERENCES system_permissions(id));
CREATE TABLE employee_roles (employee_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(employee_id,role_id), CONSTRAINT fk_er_employee FOREIGN KEY(employee_id) REFERENCES employees(id), CONSTRAINT fk_er_role FOREIGN KEY(role_id) REFERENCES system_roles(id));
