INSERT INTO system_roles(role_code,role_name,data_scope) VALUES ('ADMIN','系统管理员','ALL'),('BOSS','老板/经营负责人','ALL'),('SALES_MANAGER','销售主管','DEPARTMENT'),('SALESPERSON','业务员','SELF'),('FINANCE','财务','ALL');
INSERT INTO system_permissions(permission_code,permission_name) VALUES ('business.read.self','查看本人业务'),('business.read.department','查看本部门业务'),('business.read.all','查看全部业务'),('expense.read.self','查看本人费用'),('expense.manage','管理费用'),('profit.read.self','查看本人利润'),('profit.manage','管理利润'),('commission.read.self','查看本人提成'),('commission.manage','管理提成规则'),('commission.settle','结算提成'),('integration.h3','管理氚云数据'),('integration.dingtalk','管理钉钉集成'),('system.employee.manage','管理员工与权限');
INSERT INTO system_role_permissions SELECT r.id,p.id FROM system_roles r CROSS JOIN system_permissions p WHERE r.role_code IN ('ADMIN','BOSS');
INSERT INTO system_role_permissions SELECT r.id,p.id FROM system_roles r JOIN system_permissions p ON p.permission_code IN ('business.read.department','expense.read.self','profit.read.self','commission.read.self') WHERE r.role_code='SALES_MANAGER';
INSERT INTO system_role_permissions SELECT r.id,p.id FROM system_roles r JOIN system_permissions p ON p.permission_code IN ('business.read.self','expense.read.self','profit.read.self','commission.read.self') WHERE r.role_code='SALESPERSON';
INSERT INTO system_role_permissions SELECT r.id,p.id FROM system_roles r JOIN system_permissions p ON p.permission_code IN ('business.read.all','expense.manage','profit.manage','commission.manage','commission.settle') WHERE r.role_code='FINANCE';
INSERT IGNORE INTO employee_roles SELECT e.id,r.id FROM employees e JOIN system_roles r ON r.role_code='SALESPERSON' WHERE e.is_salesperson=1 AND e.status='ACTIVE';
